use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Rate limiter with sliding window
pub struct RateLimiter {
    windows: Mutex<HashMap<String, Vec<Instant>>>,
    max_requests: usize,
    window_duration: Duration,
}

impl RateLimiter {
    pub fn new(max_requests: usize, window_secs: u64) -> Self {
        RateLimiter {
            windows: Mutex::new(HashMap::new()),
            max_requests,
            window_duration: Duration::from_secs(window_secs),
        }
    }

    pub fn check_rate_limit(&self, key: &str) -> bool {
        let mut windows = self.windows.lock().unwrap();
        let now = Instant::now();

        // Opportunistically evict fully-expired keys to prevent unbounded
        // memory growth from an attacker supplying many distinct keys.
        let window_duration = self.window_duration;
        windows.retain(|_, timestamps| {
            timestamps.retain(|t| now.duration_since(*t) < window_duration);
            !timestamps.is_empty()
        });

        let entry = windows.entry(key.to_string()).or_insert_with(Vec::new);
        entry.retain(|t| now.duration_since(*t) < self.window_duration);
        if entry.len() >= self.max_requests {
            // Remove the entry if it is empty to avoid retaining unused keys.
            if entry.is_empty() {
                windows.remove(key);
            }
            return false;
        }
        entry.push(now);
        true
    }
}

/// Represents a resolved endpoint for OIDC discovery
#[derive(Clone, Debug)]
pub struct OidcEndpoint {
    pub issuer: String,
    pub token_endpoint: String,
    pub userinfo_endpoint: String,
}

/// Allowlist of trusted OIDC issuers
const TRUSTED_ISSUERS: &[&str] = &[
    "https://accounts.google.com",
    "https://login.microsoftonline.com",
    "https://cognito-idp.us-east-1.amazonaws.com",
];

/// Validates that a URL belongs to a trusted issuer domain
fn is_trusted_issuer_url(url: &str, issuer: &str) -> bool {
    let parsed = match url::Url::parse(url) {
        Ok(u) => u,
        Err(_) => return false,
    };

    let issuer_parsed = match url::Url::parse(issuer) {
        Ok(u) => u,
        Err(_) => return false,
    };

    // Must be HTTPS
    if parsed.scheme() != "https" {
        return false;
    }

    // Host must exactly match the trusted issuer's host
    parsed.host_str() == issuer_parsed.host_str() && parsed.host_str().is_some()
}

/// Validates that an issuer is in our allowlist
fn is_allowed_issuer(issuer_url: &str) -> bool {
    let parsed = match url::Url::parse(issuer_url) {
        Ok(u) => u,
        Err(_) => return false,
    };

    if parsed.scheme() != "https" {
        return false;
    }

    TRUSTED_ISSUERS.iter().any(|trusted| {
        let trusted_parsed = url::Url::parse(trusted).unwrap();
        parsed.host_str() == trusted_parsed.host_str()
    })
}

/// Fetches a URL with retry logic. Does NOT follow redirects.
/// All URLs must pass validation before being fetched.
fn fetch_with_retry(
    client: &reqwest::blocking::Client,
    url: &str,
    issuer: &str,
    max_retries: u32,
) -> Result<reqwest::blocking::Response, String> {
    // Validate URL belongs to trusted issuer
    if !is_trusted_issuer_url(url, issuer) {
        return Err(format!("URL does not belong to trusted issuer: {}", url));
    }

    let mut attempts = 0;

    loop {
        if attempts >= max_retries {
            return Err("Max retries exceeded".to_string());
        }
        attempts += 1;

        let response = client
            .get(url)
            .send()
            .map_err(|e| format!("Request failed: {}", e))?;

        match response.status().as_u16() {
            200 => return Ok(response),
            301 | 302 | 307 | 308 => {
                // Do NOT follow redirects - this prevents SSRF via redirect
                return Err("Redirects are not allowed for security".to_string());
            }
            429 => {
                std::thread::sleep(Duration::from_millis(100 * attempts as u64));
            }
            503 => {
                std::thread::sleep(Duration::from_millis(200 * attempts as u64));
            }
            _ => return Err(format!("Unexpected status: {}", response.status())),
        }
    }
}

/// OIDC Discovery: fetches the well-known configuration
pub fn discover_oidc_config(
    rate_limiter: &RateLimiter,
    client: &reqwest::blocking::Client,
    issuer_url: &str,
    client_id: &str,
) -> Result<OidcEndpoint, String> {
    // Rate limit per client
    if !rate_limiter.check_rate_limit(client_id) {
        return Err("Rate limit exceeded".to_string());
    }

    // Validate issuer is in allowlist
    if !is_allowed_issuer(issuer_url) {
        return Err("Issuer not in trusted allowlist".to_string());
    }

    let well_known = format!("{}/.well-known/openid-configuration", issuer_url.trim_end_matches('/'));

    // Fetch with retries - no redirect following
    let resp = fetch_with_retry(client, &well_known, issuer_url, 5)?;

    let body: serde_json::Value = resp
        .json()
        .map_err(|e| format!("JSON parse failed: {}", e))?;

    let token_endpoint = body["token_endpoint"]
        .as_str()
        .ok_or("Missing token_endpoint")?
        .to_string();

    let userinfo_endpoint = body["userinfo_endpoint"]
        .as_str()
        .ok_or("Missing userinfo_endpoint")?
        .to_string();

    // Validate discovered endpoints belong to the same issuer
    if !is_trusted_issuer_url(&token_endpoint, issuer_url) {
        return Err("token_endpoint does not match issuer".to_string());
    }
    if !is_trusted_issuer_url(&userinfo_endpoint, issuer_url) {
        return Err("userinfo_endpoint does not match issuer".to_string());
    }

    Ok(OidcEndpoint {
        issuer: issuer_url.to_string(),
        token_endpoint,
        userinfo_endpoint,
    })
}

/// Exchange authorization code for tokens
pub fn exchange_code(
    rate_limiter: &RateLimiter,
    client: &reqwest::blocking::Client,
    endpoint: &OidcEndpoint,
    code: &str,
    client_id: &str,
    client_secret: &str,
    redirect_uri: &str,
) -> Result<serde_json::Value, String> {
    if !rate_limiter.check_rate_limit(client_id) {
        return Err("Rate limit exceeded".to_string());
    }

    // Validate token endpoint belongs to trusted issuer
    if !is_trusted_issuer_url(&endpoint.token_endpoint, &endpoint.issuer) {
        return Err("Token endpoint validation failed".to_string());
    }

    let resp = client
        .post(&endpoint.token_endpoint)
        .form(&[
            ("grant_type", "authorization_code"),
            ("code", code),
            ("client_id", client_id),
            ("client_secret", client_secret),
            ("redirect_uri", redirect_uri),
        ])
        .send()
        .map_err(|e| format!("Token exchange failed: {}", e))?;

    resp.json().map_err(|e| format!("Token parse failed: {}", e))
}
